{
    text   (rx)  : ORIGIN = {{flashOrigin}},  LENGTH = {{flashLength}}
    data   (rw!x): ORIGIN = {{sramOrigin}},   LENGTH = {{sramLength}}
    eeprom (rw!x): ORIGIN = {{eepromOrigin}}, LENGTH = {{eepromLength}}
}

SECTIONS
{
    .text :
    {
        KEEP(*(.vectors))
        *(.text*)
        *(.rodata*)
        KEEP(*(.init*))
        KEEP(*(.fini*))
    } > text

    .data : AT (ADDR(.text) + SIZEOF(.text))
    {
        __data_start = .;
        *(.data*)
        __data_end = .;
    } > data

    .bss :
    {
        __bss_start = .;
        *(.bss*)
        *(COMMON)
        __bss_end = .;
        _end = .;
    } > data

    .eeprom :
    {
        *(.eeprom*)
    } > eeprom
}

