extern uint8_t _etext;
extern uint8_t _sdata;
extern uint8_t _edata;
extern uint8_t _sbss;
extern uint8_t _ebss;

static void {{startupFunction}}(void)
{
    uint8_t *src = &_etext;
    for (uint8_t *dst = &_sdata; dst < &_edata; )
    {
        *dst++ = *src++;
    }

    for (uint8_t *dst = &_sbss; dst < &_ebss; )
    {
        *dst++ = 0;
    }
}

/* ATmega328P 32 KiB flash split. Link either the bootloader or the application image, not both at once. */
MEMORY
{
    APP_FLASH  (rx) : ORIGIN = 0x0000,        LENGTH = {{bootStartAddress}}
    BOOT_FLASH (rx) : ORIGIN = {{bootStartAddress}}, LENGTH = {{bootSizeBytes}}
    RAM        (rw) : ORIGIN = 0x800100,      LENGTH = 2K
    EEPROM     (rw) : ORIGIN = 0x810000,      LENGTH = 1K
}

/* Application image: place .text in APP_FLASH.
   Bootloader image: place .text in BOOT_FLASH and program BOOTRST/BOOTSZ fuses accordingly. */
SECTIONS
{
    .vectors : { KEEP(*(.vectors .vectors.*)) } > {{imageRegion}}
    .text    : { *(.text .text.*) *(.rodata .rodata.*) _etext = .; } > {{imageRegion}}
    .data    : AT(_etext) { _sdata = .; *(.data .data.*) _edata = .; } > RAM
    .bss (NOLOAD) : { _sbss = .; *(.bss .bss.* COMMON) _ebss = .; } > RAM
}

/* Bootloader reset / application jump pattern. Verify IVSEL, BOOTRST and watchdog handling for your device. */
typedef void (*app_entry_t)(void);

#define APP_START_ADDRESS ((uint16_t){{appStartAddress}})

static void {{jumpFunction}}(void)
{
